//! Generates the demonstration data set committed at `samples/riverside-works-2024.csv`.
//!
//! The sample data is *synthetic and says so*. It is not a real site's meter
//! export, and Tonans must never imply that it is. It exists so that a new user has
//! something to open, and so that the end-to-end tests have a realistic year of
//! intervals to chew on.
//!
//! It is generated by this program rather than hand-written so that anyone can see
//! exactly what shaped it: a light-industrial load with a weekday shift pattern, a
//! south-facing rooftop array, a summer-peaking time-of-use tariff, and a winter
//! temperature profile. Deterministic - there is no randomness, only a fixed
//! pseudo-random sequence - so re-running it reproduces the committed file byte for
//! byte.
//!
//! ```text
//! cargo run --example generate_demo_csv -p tonans-core > samples/riverside-works-2024.csv
//! ```

use chrono::{DateTime, Datelike, TimeDelta, Timelike, Utc};
use chrono_tz::America::New_York;

/// A fixed-seed xorshift. Not for cryptography; for a repeatable jitter that keeps
/// the sample from looking like a sine wave.
struct Noise(u64);

impl Noise {
    fn next(&mut self) -> f64 {
        let mut x = self.0;
        x ^= x << 13;
        x ^= x >> 7;
        x ^= x << 17;
        self.0 = x;
        // Map to -1.0 ..= 1.0.
        (x >> 11) as f64 / (1u64 << 53) as f64 * 2.0 - 1.0
    }
}

fn main() {
    // 2024 is a leap year; we take the 365 days from 1 January to 30 December so the
    // file is exactly 8,760 hourly intervals, which is what the annualization factor
    // assumes.
    let start: DateTime<Utc> = DateTime::parse_from_rfc3339("2024-01-01T00:00:00-05:00")
        .expect("a valid instant")
        .with_timezone(&Utc);

    let mut noise = Noise(0x5eed_1234_abcd_0001);
    println!("timestamp,load_kw,critical_load_kw,pv_kw,import_price_per_kwh,export_price_per_kwh,demand_period,ambient_c");

    for hour in 0..8_760i64 {
        let instant = start + TimeDelta::hours(hour);
        let local = instant.with_timezone(&New_York);
        let (month, weekday, hour_of_day) = (
            local.month(),
            local.weekday().num_days_from_monday(),
            local.hour(),
        );
        let weekend = weekday >= 5;

        // How far into summer we are: 0.0 at the January solstice, 1.0 at the July one.
        // Everything seasonal is expressed in terms of this, so the sign cannot get
        // inverted without the whole file obviously being wrong.
        let season = ((f64::from(month) - 7.0) / 6.0 * std::f64::consts::PI).cos();
        let summer_fraction = (1.0 + season) / 2.0;

        // Load: a two-shift light-industrial profile. Base plant load all day, a
        // large step during the shift, a smaller one at the weekend.
        let base = 48.0;
        let shift = if weekend {
            match hour_of_day {
                8..=16 => 42.0,
                _ => 4.0,
            }
        } else {
            match hour_of_day {
                6 => 60.0,
                7..=15 => 132.0,
                16..=18 => 88.0,
                19..=21 => 30.0,
                _ => 6.0,
            }
        };
        // Cooling through summer afternoons; a smaller heating load on winter mornings.
        let cooling = if (5..=9).contains(&month) && (11..=19).contains(&hour_of_day) {
            36.0 * summer_fraction
        } else {
            0.0
        };
        let heating = if (month >= 11 || month <= 3) && (5..=9).contains(&hour_of_day) {
            15.0 * (1.0 - summer_fraction)
        } else {
            0.0
        };
        let load = (base + shift + cooling + heating + noise.next() * 5.0).max(8.0);

        // Critical load: the plant's servers, freezers, and safety systems. Always a
        // strict subset of total load, which the importer enforces.
        let critical = (18.0 + 4.0 * summer_fraction + noise.next() * 1.5).clamp(8.0, load * 0.9);

        // A 220 kW rooftop array. Longer days and a higher sun in summer, a cloud
        // factor on top.
        let solar_noon = 12.5;
        let day_length = 5.4 + 2.8 * summer_fraction;
        let elevation = 1.0 - ((f64::from(hour_of_day) - solar_noon) / day_length).powi(2);
        let clear_sky = if elevation > 0.0 {
            220.0 * elevation * (0.60 + 0.40 * summer_fraction)
        } else {
            0.0
        };
        let cloud = (0.72 + 0.28 * noise.next()).clamp(0.12, 1.0);
        let pv = (clear_sky * cloud).max(0.0);

        // Time-of-use energy, with a summer on-peak window. Real tariffs are more
        // baroque; this one is deliberately simple enough to check by hand.
        let summer = (6..=9).contains(&month);
        let on_peak = !weekend && (14..=19).contains(&hour_of_day);
        let import_price = match (summer, on_peak) {
            (true, true) => 0.2840,
            (true, false) => 0.1190,
            (false, true) => 0.1810,
            (false, false) => 0.0980,
        };
        let export_price = 0.0410;
        let period = if on_peak { "on-peak" } else { "off-peak" };

        // Ambient temperature, for battery derating. About 1 C in January and 25 C
        // in July, warmest in the mid-afternoon.
        let daily =
            ((f64::from(hour_of_day) - 15.0) / 24.0 * 2.0 * std::f64::consts::PI).cos() * 5.5;
        let ambient = 1.0 + 24.0 * summer_fraction + daily + noise.next() * 1.2;

        println!(
            "{timestamp},{load:.2},{critical:.2},{pv:.2},{import_price:.4},{export_price:.4},{period},{ambient:.1}",
            timestamp = instant.with_timezone(&New_York).to_rfc3339(),
        );
    }
}
